use crate::application::provider_repo::ProviderRepository;
use crate::domain::{
    error::AppError,
    provider_profile::{Location, ProviderProfile},
};
use async_trait::async_trait;
// use crate::schema::providers; // Once schema is generated by diesel

pub struct DieselProviderRepository {
    pool: crate::infrastructure::state::DbPool,
}

impl DieselProviderRepository {
    pub fn new(pool: crate::infrastructure::state::DbPool) -> Self {
        Self { pool }
    }
}

#[async_trait]
impl ProviderRepository for DieselProviderRepository {
    async fn find_within_radius(
        &self,
        _target: &Location,
        _radius_meters: f64,
        _service_type: &str,
    ) -> Result<Vec<ProviderProfile>, AppError> {
        // Will implement diesel PostGIS query later
        let _conn = self
            .pool
            .get()
            .map_err(|e| AppError::InternalServerError(format!("Pool error: {}", e)))?;

        Ok(vec![])
    }

    async fn create_provider(&self, _provider: &ProviderProfile) -> Result<(), AppError> {
        let _conn = self
            .pool
            .get()
            .map_err(|e| AppError::InternalServerError(format!("Pool error: {}", e)))?;

        Ok(())
    }
}
